CREATE FUNCTION public.submit_public_application(_slug text,_cat uuid,_name text,_email text,_phone text,_home text,_pets text,_message text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; aid uuid; BEGIN SELECT id INTO sid FROM public.shelters WHERE slug=_slug; IF sid IS NULL OR NOT EXISTS(SELECT 1 FROM public.cats WHERE id=_cat AND shelter_id=sid AND stage='available') THEN RAISE EXCEPTION 'Cat is not available at this rescue'; END IF; IF length(trim(_name))<1 OR length(_name)>120 OR length(_email)>200 OR _email NOT LIKE '%@%.%' OR length(_phone)>40 OR length(_home)>120 OR length(_pets)>300 OR length(_message)>2000 THEN RAISE EXCEPTION 'Invalid application'; END IF; INSERT INTO public.applications(shelter_id,cat_id,applicant_name,email,phone,home_type,other_pets,message) VALUES(sid,_cat,trim(_name),_email,_phone,_home,_pets,_message) RETURNING id INTO aid; RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.submit_public_application(text,uuid,text,text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_public_application(text,uuid,text,text,text,text,text,text) TO anon,authenticated,service_role;
CREATE FUNCTION public.accept_shelter_invite(_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.shelter_invites; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF EXISTS(SELECT 1 FROM public.shelter_members WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Already a member of a rescue'; END IF; SELECT * INTO inv FROM public.shelter_invites WHERE token=_token AND lower(email)=lower((SELECT email FROM auth.users WHERE id=auth.uid())) AND used_at IS NULL AND expires_at>now() FOR UPDATE; IF inv.id IS NULL THEN RAISE EXCEPTION 'Invalid or expired invitation'; END IF; INSERT INTO public.shelter_members(shelter_id,user_id,role,email) SELECT inv.shelter_id,id,'staff',email FROM auth.users WHERE id=auth.uid(); UPDATE public.shelter_invites SET used_at=now() WHERE id=inv.id; END $$;
REVOKE ALL ON FUNCTION public.accept_shelter_invite(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.accept_shelter_invite(uuid) TO authenticated;